  'addingATorrentInQBittorrentFillsInTheSavePathFromTheServerUsingItsDefaultLocationOrThePathTheChosenCategoryDefinesSoItNoLongerHasToBeTypedOutForEveryTorrent': 'L\'ajout d\'un torrent dans qBittorrent préremplit le chemin d\'enregistrement depuis le serveur, en utilisant son emplacement par défaut ou le chemin défini par la catégorie choisie, donc plus besoin de le retaper pour chaque torrent.',
  'addingThingsInLidarrWorksAgainAddingAnArtistIndexerDownloadClientImportListNotificationTagRootFolderCustomFormatOrAnyOfTheProfilesWasRefusedByTheServerAsWasGrabbingAReleaseFromAnInteractiveSearchAtriumWasSendingEmptyFieldsThatLidarrWillNotAcceptAndItRejectedTheWholeRequestWithoutSayingWhichPartItDisliked': 'L\'ajout de choses dans Lidarr fonctionne à nouveau. L\'ajout d\'un artiste, indexeur, client de téléchargement, liste d\'import, notification, balise, dossier racine, format personnalisé ou de l\'un des profils était refusé par le serveur, tout comme le grab d\'une release depuis une recherche interactive. Atrium envoyait des champs vides que Lidarr n\'accepte pas, et il rejetait la requête entière sans dire quelle partie lui déplaisait.',
