  'adguardHomeIsASupportedServiceInBetaHomeTurnsProtectionOnOrOffOrPausesItForATimeAndShowsTheDNSStatisticsWithTheTopClientsDomainsAndUpstreamsWhereADomainCanBeBlockedOrUnblockedFromItsRowTheQueryLogIsSearchedAndFilteredTheWayTheWebUIDoesItAndAQueryOpensInFullToBlockOrUnblockItsNameForEveryoneOrForOneClientOrToDisallowTheClientClientsListsThePersistentAndRuntimeClientsAndAPersistentClientCanBeAddedChangedOrDeletedWithItsOwnProtectionSettingsBlockedServicesAndUpstreamServersADashboardWidgetShowsTheStateWithPauseAndResumeTheFilterListsAndTheSettingsOfTheServerAreStillToCome': 'AdGuard Home est un service pris en charge, en bêta. Accueil active ou désactive la protection, ou la met en pause pour un temps, et affiche les statistiques DNS avec les principaux clients, domaines et serveurs amont, où un domaine peut être bloqué ou débloqué depuis sa ligne. Le journal des requêtes est recherché et filtré comme dans l\'interface web, et une requête s\'ouvre en entier, pour bloquer ou débloquer son nom pour tout le monde ou pour un seul client, ou pour interdire le client. Clients liste les clients persistants et ceux en cours d\'exécution, et un client persistant peut être ajouté, modifié ou supprimé, avec ses propres paramètres de protection, services bloqués et serveurs amont. Un widget du tableau de bord montre l\'état, avec Pause et Reprendre. Les listes de filtres et les paramètres du serveur restent à venir.',
