  'delugeEMessage1': 'Deluge : {0}',
  'delugeHasNotReceivedThisTorrentSMetadataYet': 'Deluge n\'a pas encore reçu les métadonnées de ce torrent.',
  'delugeIsRedesignedToMatchQBittorrentAndTransmissionDownloadUploadAndFreeSpaceSitOnThreeTilesWithTheSessionPauseAndSpeedLimitsUnderThemAndAddingATorrentMovesToAFloatingButtonTheStateFiltersMoveIntoASideDrawerWithAFilteredStripAndADotOnTheFilterButtonWhileOneIsOnTorrentsShowAsCardsWithTheirSpeedsRatioAndETAWithTheActionsOnALongPressAndTheDetailScreenIsBuiltFromPanelsWithPeerCountryFlagsAndAMenuHoldingEveryTorrentAction': 'Deluge est repensé pour ressembler à qBittorrent et Transmission. Téléchargement, envoi et espace libre tiennent sur trois tuiles, avec la pause de session et les limites de vitesse dessous, et l\'ajout d\'un torrent passe par un bouton flottant. Les filtres d\'état passent dans un tiroir latéral, avec une bande « Filtré » et un point sur le bouton de filtre tant qu\'un filtre est actif. Les torrents s\'affichent en cartes avec leurs vitesses, ratio et ETA, les actions au appui long, et l\'écran de détail est composé de panneaux, avec les drapeaux de pays des pairs et un menu regroupant toutes les actions.',
