  'myspeedIsASupportedServiceItsStatusTabShowsWhetherATestIsRunningAndCanStartOneWithTheLastDayOfResultsBeneathHistoryListsEveryTestWithAveragesAndASearchByIdConfigShowsTheScheduleTheProviderAndTheStorageFiguresPasswordProtectedInstancesWorkAndADashboardWidgetShowsTheLatestFiguresAndRunsATestFromTheBoard': 'MySpeed est un service pris en charge. Son onglet Statut indique si un test est en cours et permet d\'en lancer un, avec les résultats du dernier jour en dessous ; Historique liste chaque test avec les moyennes et une recherche par id ; Config montre le planning, le fournisseur et les chiffres de stockage. Les instances protégées par mot de passe fonctionnent, et un widget du tableau de bord montre les derniers chiffres et lance un test depuis le tableau.',
