  'qbittorrentCanEditATorrentSTrackersEditTrackersOpensThemAsTextOneURLPerLineWithABlankLineBetweenTiersAndShowsWhatSaveWillAddAndRemoveEachTrackerSMenuCanCopyEditOrRemoveItAndRowsShowTheirTier': 'qBittorrent permet de modifier les trackers d\'un torrent. Modifier les trackers les ouvre en texte, une URL par ligne avec une ligne vide entre les niveaux, et montre ce que Enregistrer ajoutera et retirera. Le menu de chaque tracker permet de copier, modifier ou supprimer, et les lignes indiquent leur niveau.',
  'qbittorrentCanSkipTheHashCheckWhenYouAddATorrentWhoseFilesAreAlreadyOnDiskInsteadOfRecheckingTheWholeThing': 'qBittorrent peut ignorer la vérification du hash quand vous ajoutez un torrent dont les fichiers sont déjà sur le disque, au lieu de tout revérifier.',
  'qbittorrentGainedASettingsPageCoveringWhatItsOwnWebInterfaceOffersAcrossSystemBehaviourDownloadsConnectionSpeedBitTorrentRSSWebUIAndAdvanced': 'qBittorrent a gagné une page de paramètres couvrant ce qu\'offre sa propre interface web, sur système, comportement, téléchargements, connexion, vitesse, BitTorrent, RSS, interface web et avancé.',
  'qbittorrentGainedTagManagementFilterYourTorrentsByTagAndCopyATrackerURLStraightFromTheTrackersList': 'qBittorrent a gagné la gestion des balises : filtrez vos torrents par balise, et copiez l\'URL d\'un tracker directement depuis la liste des trackers.',
  'qbittorrentHasAnExecutionLogTabReadWhenYouOpenItWithCopy': 'qBittorrent a un onglet de journal d\'exécution, lu à l\'ouverture, avec copie.',
  'qbittorrentMarksTorrentsAsPrivateOrPublicTheBadgeIsInTheListOnQBittorrent50AndLaterAndOnTheTorrentScreenFrom451': 'qBittorrent marque les torrents comme privés ou publics. Le badge est dans la liste sur qBittorrent 5.0 et ultérieur, et sur l\'écran du torrent depuis la 4.5.1.',
  'qbittorrentRemembersHowYouSortedTheListWhateverYouLastChoseIsWhatYouGetNextTimeYouOpenTheAppKeptSeparatelyForEachServerRatherThanResettingToNewestFirstOnEveryLaunch': 'qBittorrent se souvient de la façon dont vous avez trié la liste. Ce que vous avez choisi en dernier est ce que vous retrouvez à la prochaine ouverture de l\'app, conservé séparément pour chaque serveur, au lieu de revenir au plus récent à chaque lancement.',
  'qbittorrentSABnzbdProwlarrBazarrSeerrTautulliAndGlancesModules': 'Modules qBittorrent, SABnzbd, Prowlarr, Bazarr, Seerr, Tautulli et Glances.',
  'qbittorrentSABnzbdTransmission': 'qBittorrent, SABnzbd, Transmission, …',
  'qbittorrentSTrackerErrorAndUnreachableStatesNoLongerShowAsUnknown': 'Les états Erreur de tracker et Injoignable de qBittorrent ne s\'affichent plus comme Inconnu.',
  'qbittorrentShowsItsExternalIPv4AndIPv6AddressInSettingsSystemOnQBittorrent50AndLater': 'qBittorrent affiche son adresse IPv4 et IPv6 externe dans Paramètres > Système, sur qBittorrent 5.0 et ultérieur.',
  'qbittorrentTorrentsCanBeFilteredByTrackerWithACountNextToEachOne': 'Les torrents de qBittorrent peuvent être filtrés par tracker, avec un compte à côté de chacun.',
