  'slskdSLogsTabExplainsThatTheAPIKeyNeedsTheAdministratorRoleInsteadOfShowingARawError': 'L\'onglet Journaux de slskd explique que la clé API doit avoir le rôle Administrateur au lieu d\'afficher une erreur brute.',
  'slskdSVersionShowsAs0262RatherThan02620': 'La version de slskd s\'affiche 0.26.2 au lieu de 0.26.2.0.',
  'slskdTheSoulseekClientIsASupportedServiceInBetaTransfersListsDownloadsAndUploadsByPeerAndFolderOrAsOneListSearchShowsResultsAsAlbumsOrTracksWithFormatBitrateAndFreeSlotFiltersAndAOneTapAlbumDownloadBrowseOpensAPeerSSharesAsAFolderTreeCommunityHoldsDirectMessagesAndChatRoomsAndSystemCoversTheServerConnectionSharesLogsAndTransferStatistics': 'slskd, le client Soulseek, est un service pris en charge, en bêta. Transferts liste les téléchargements et envois par pair et dossier ou en une seule liste. La recherche affiche les résultats en albums ou pistes, avec des filtres de format, débit et emplacement libre, et le téléchargement d\'un album en un toucher. Parcourir ouvre les partages d\'un pair en arbre de dossiers, Communauté regroupe les messages privés et les salons de discussion, et Système couvre la connexion au serveur, les partages, les journaux et les statistiques de transferts.',
