  'theFilterButtonOnTheQBittorrentScreenOpensTheFilterDrawerAgainItHadBeenAskingTheWrongPartOfTheScreenWhichAnsweredByDoingNothingAtAllSoTheButtonLookedDeadWhileSwipingInFromTheEdgeStillWorked': 'Le bouton de filtre de l\'écran qBittorrent rouvre le tiroir de filtres. Il interrogeait la mauvaise partie de l\'écran, qui répondait en ne faisant rien, donc le bouton semblait mort alors que le balayage depuis le bord fonctionnait toujours.',
  'theHealthCheckNoLongerMistakesTheLoginPageOfAReverseProxyForAWorkingServerItUsedToFollowTheRedirectToASignInPageGetANormalAnswerBackAndReportTheServiceAsOnlineItNowRecognisesALoginPageAndShowsAWarningInstead': 'Le contrôle de santé ne prend plus la page de connexion d\'un proxy inverse pour un serveur fonctionnel. Il suivait auparavant la redirection vers une page de connexion, recevait une réponse normale, et déclarait le service en ligne. Il reconnaît maintenant une page de connexion et affiche un avertissement à la place.',
