  'theQBittorrentSettingsListTheNetworkInterfacesTheServerActuallyHas': 'Les paramètres de qBittorrent listent les interfaces réseau que le serveur possède réellement.',
  'theQBittorrentTorrentListAsksOnlyForWhatChangedSinceTheLastRefreshTheWayTheQBittorrentWebUIDoesSoALargeLibraryLoadsFasterAndUsesFarLessDataHowOftenItRefreshesIsNowSetPerInstanceInItsForm5SecondsByDefaultItWas3': 'La liste des torrents de qBittorrent ne demande que ce qui a changé depuis la dernière actualisation, comme le fait l\'interface web de qBittorrent, donc une grande bibliothèque se charge plus vite et consomme beaucoup moins de données. La fréquence d\'actualisation se règle maintenant par instance dans son formulaire, 5 secondes par défaut (c\'était 3).',
