  'unraidIsNowASupportedServiceTheArrayTabShowsParityAndDataDisksWithPerDiskUsageTemperatureAndHealthAlongsideTheStateOfTheLastParityCheckTheSystemTabCoversPerCoreCPULoadMemoryNetworkAndAnAboutCardNamingTheProcessorUptimeKernelMemorySlotsAndHostnameDockerContainersListWithTheirPortsAndUptimeOpenToADetailSheetAndCanBeStartedStoppedPausedAndResumedVirtualMachinesCanBeStartedShutDownPausedResumedRebootedForceStoppedAndResetItIsMarkedBetaWhileItSettlesIn': 'Unraid est désormais un service pris en charge. L\'onglet du tableau montre les disques de parité et de données avec l\'utilisation, la température et la santé de chacun, ainsi que l\'état de la dernière vérification de parité. L\'onglet système couvre la charge CPU par cœur, la mémoire, le réseau, et une carte À propos nommant le processeur, la disponibilité, le noyau, les emplacements mémoire et le nom d\'hôte. Les conteneurs Docker sont listés avec leurs ports et leur disponibilité, ouvrent une feuille de détail, et peuvent être démarrés, arrêtés, mis en pause et repris. Les machines virtuelles peuvent être démarrées, arrêtées, mises en pause, reprises, redémarrées, arrêtées de force et réinitialisées. Il est marqué bêta le temps de se stabiliser.',
